import{_ as e,o as r,c as a,a0 as i}from"./chunks/framework.DW5bL-_G.js";const k=JSON.parse('{"title":"竞品对比与产品定位","description":"对比 Pickr、iro.js、Coloris、react-colorful、react-color 等成熟颜色选择器，说明 ew-color-picker 的差异、优势、局限与适用场景。","frontmatter":{"title":"竞品对比与产品定位","description":"对比 Pickr、iro.js、Coloris、react-colorful、react-color 等成熟颜色选择器，说明 ew-color-picker 的差异、优势、局限与适用场景。"},"headers":[],"relativePath":"guide/comparison.md","filePath":"guide/comparison.md"}'),d={name:"guide/comparison.md"};function o(s,t,l,n,c,h){return r(),a("div",null,[...t[0]||(t[0]=[i(`<h1 id="竞品对比与产品定位" tabindex="-1">竞品对比与产品定位 <a class="header-anchor" href="#竞品对比与产品定位" aria-label="Permalink to &quot;竞品对比与产品定位&quot;">​</a></h1><p>选颜色选择器时，真正要回答的问题不是「谁功能多」，而是「谁更适合你的 UI 体系」。本页先给出定位，再横向对比几款成熟方案，最后说明各自的适用边界。</p><h2 id="一句话定位" tabindex="-1">一句话定位 <a class="header-anchor" href="#一句话定位" aria-label="Permalink to &quot;一句话定位&quot;">​</a></h2><p>ew-color-picker 不是一套「成品皮肤」，而是一个 <strong>可组装的颜色选择器底座</strong>：核心只维护颜色与事件，所有界面部件都是独立插件，团队可以保留需要的部分、替换不需要的部分，或者基于同一套插件协议写自己的 UI。</p><p>适合：中后台系统、低代码平台、组件库、需要和现有设计体系深度融合的产品。 不适合：只想要一个开箱即用、无需定制的单点选色场景（这类需求用原生 <code>input[type=color]</code> 或 Coloris 更省事）。</p><h2 id="横向对比" tabindex="-1">横向对比 <a class="header-anchor" href="#横向对比" aria-label="Permalink to &quot;横向对比&quot;">​</a></h2><p>下表数据来自 npm registry（unpackedSize 与最后发布时间，统计于 2026-10-30），仅作体量参考；功能列按各自官方文档的公开能力整理。</p><table tabindex="0"><thead><tr><th>方案</th><th>形态</th><th>框架约束</th><th>扩展方式</th><th>体积（unpacked）</th><th>最近发布</th></tr></thead><tbody><tr><td><strong>ew-color-picker</strong></td><td>13 个 npm 包，插件化</td><td>无（原生 DOM）</td><td>插件注册 / 自写插件</td><td>聚合包 543.8 KB，核心包 <code>core.min</code> 11 KB（gzip 3 KB）</td><td>2026-10</td></tr><tr><td><a href="https://github.com/Simonwep/pickr" target="_blank" rel="noreferrer">Pickr</a></td><td>单包，UMD/ESM</td><td>无</td><td>主题（classic/monolith/nano）+ 选项</td><td>280.3 KB</td><td>2026-09</td></tr><tr><td><a href="https://github.com/jaames/iro.js" target="_blank" rel="noreferrer">iro.js</a></td><td>单包</td><td>无</td><td>选项 + 组件组合</td><td>231.4 KB</td><td>2021-07</td></tr><tr><td><a href="https://github.com/melloware/coloris" target="_blank" rel="noreferrer">Coloris</a></td><td>单包 + 一份 CSS</td><td>无</td><td>CSS 变量主题 + 选项</td><td>152.2 KB</td><td>2026-10</td></tr><tr><td><a href="https://github.com/omgovich/react-colorful" target="_blank" rel="noreferrer">react-colorful</a></td><td>React 组件</td><td>React</td><td>组合组件</td><td>398.4 KB</td><td>2026-09</td></tr><tr><td><a href="https://github.com/casesandberg/react-color" target="_blank" rel="noreferrer">react-color</a></td><td>React 组件集</td><td>React</td><td>选择不同 Picker 组件</td><td>436.3 KB</td><td>2020-10</td></tr><tr><td><a href="https://github.com/linx4200/vue-color" target="_blank" rel="noreferrer">vue-color</a></td><td>Vue 组件集</td><td>Vue</td><td>选择不同 Picker 组件</td><td>391.5 KB</td><td>2025-10</td></tr><tr><td><a href="https://github.com/uiwjs/react-color" target="_blank" rel="noreferrer">@uiw/react-color</a></td><td>React 组件集</td><td>React</td><td>按组件引入</td><td>210.8 KB</td><td>2026-05</td></tr><tr><td>原生 <code>input[type=color]</code></td><td>浏览器内置</td><td>无</td><td>无（样式不可控）</td><td>0</td><td>随浏览器</td></tr><tr><td>Spectrum</td><td>jQuery 插件</td><td>jQuery</td><td>选项</td><td>1804.2 KB</td><td>2020-05</td></tr></tbody></table><p>需要强调的一点：体量数字不能直接等价为运行时开销。ew-color-picker 的聚合包体积主要来自三份产物（UMD、UMD.min、ESM）和 <code>.d.ts</code> 声明，实际引入的最小运行时是 <code>index.min.js</code> <strong>79 KB（gzip 18 KB）</strong>，按需只用核心时是 <strong>11 KB（gzip 3 KB）</strong>。</p><h2 id="ew-color-picker-的优势" tabindex="-1">ew-color-picker 的优势 <a class="header-anchor" href="#ew-color-picker-的优势" aria-label="Permalink to &quot;ew-color-picker 的优势&quot;">​</a></h2><h3 id="_1-插件是「结构可替换」-不只是「主题可换」" tabindex="-1">1. 插件是「结构可替换」，不只是「主题可换」 <a class="header-anchor" href="#_1-插件是「结构可替换」-不只是「主题可换」" aria-label="Permalink to &quot;1. 插件是「结构可替换」，不只是「主题可换」&quot;">​</a></h3><p>多数同类库的定制方式是换主题、改 CSS 变量或改配置项，UI 的组成结构固定。ew-color-picker 把颜色盒、面板、色相滑块、透明度滑块、输入框、数字输入框、按钮、预定义色板、模式切换器都拆成独立插件，注册哪些、顺序如何、要不要自己的插件，都由使用者决定。</p><div class="language-ts vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ewColorPicker </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@ew-color-picker/core&#39;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Panel </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@ew-color-picker/panel&#39;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Hue </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@ew-color-picker/hue&#39;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 只注册需要的部件，其余不引入</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ewColorPicker.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">use</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(Panel).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">use</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(Hue)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="_2-框架无关-可做框架封装的底座" tabindex="-1">2. 框架无关，可做框架封装的底座 <a class="header-anchor" href="#_2-框架无关-可做框架封装的底座" aria-label="Permalink to &quot;2. 框架无关，可做框架封装的底座&quot;">​</a></h3><p>核心不依赖 React / Vue / jQuery，只操作原生 DOM 与事件。这意味着同一套插件协议可以同时被 React、Vue、Angular 或低代码运行时封装，而不需要为每个框架维护一套实现。</p><h3 id="_3-单一数据源-实例级事件总线" tabindex="-1">3. 单一数据源 + 实例级事件总线 <a class="header-anchor" href="#_3-单一数据源-实例级事件总线" aria-label="Permalink to &quot;3. 单一数据源 + 实例级事件总线&quot;">​</a></h3><p>任何插件改色都只走 <code>core.setColor()</code>，再由 <code>change</code> 事件驱动其他插件同步，不存在多份颜色状态；每个实例有独立事件总线、DOM 与插件实例，多实例场景不会互相污染。</p><h3 id="_4-开箱即用的完整能力" tabindex="-1">4. 开箱即用的完整能力 <a class="header-anchor" href="#_4-开箱即用的完整能力" aria-label="Permalink to &quot;4. 开箱即用的完整能力&quot;">​</a></h3><p>聚合包默认就带 Hex / RGB / HSL 模式切换、透明度调节、预定义色板、清空/确定按钮与输入校验，不需要像 <code>react-colorful</code> 那样自己拼输入框和按钮。</p><h3 id="_5-全量-typescript-类型" tabindex="-1">5. 全量 TypeScript 类型 <a class="header-anchor" href="#_5-全量-typescript-类型" aria-label="Permalink to &quot;5. 全量 TypeScript 类型&quot;">​</a></h3><p>每个包都输出 <code>.d.ts</code>，插件通过 <code>declare module</code> 扩展核心配置类型，使用自定义插件时配置项也能获得类型提示。</p><h3 id="_6-文档即产品的一部分" tabindex="-1">6. 文档即产品的一部分 <a class="header-anchor" href="#_6-文档即产品的一部分" aria-label="Permalink to &quot;6. 文档即产品的一部分&quot;">​</a></h3><p>中英双语文档站、逐项 API 说明、插件独立文档，并额外提供 <code>llms.txt</code> / <code>llms-full.txt</code>，方便人和 AI 一起检索接入方式。</p><h2 id="需要正视的局限" tabindex="-1">需要正视的局限 <a class="header-anchor" href="#需要正视的局限" aria-label="Permalink to &quot;需要正视的局限&quot;">​</a></h2><ul><li><strong>生态与社区规模小</strong>：下载量、第三方教程、Issue 沉淀都无法与 Pickr、react-color 相比，遇到冷门问题更多要靠读源码。</li><li><strong>没有官方框架封装</strong>：React / Vue 用户需要自己写一层薄封装（或等社区提供）。</li><li><strong>不支持渐变、多色选择与图片取色</strong>：这类需求目前要选 iro.js 或专门的渐变选择器。</li><li><strong>包数量多</strong>：首次接入需要理解「核心 + 插件」的心智模型，比单包方案多一步。</li><li><strong>包的绝对体积不占优</strong>：聚合包 543.8 KB（含声明与三份产物）超过 Pickr、Coloris 的整包体积；优势在于可以按需裁剪到很小。</li></ul><h2 id="选型建议" tabindex="-1">选型建议 <a class="header-anchor" href="#选型建议" aria-label="Permalink to &quot;选型建议&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你的场景</th><th>建议</th></tr></thead><tbody><tr><td>只要一个能选色的输入控件，样式不重要</td><td>原生 <code>input[type=color]</code></td></tr><tr><td>需要轻量、无依赖、主题化但不改结构</td><td>Coloris 或 Pickr</td></tr><tr><td>React 项目只要一个面板/滑块</td><td>react-colorful</td></tr><tr><td>Vue 项目需要现成组件集</td><td>vue-color 或 @uiw/react-color</td></tr><tr><td>需要渐变、色彩空间转换、游戏/可视化场景</td><td>iro.js</td></tr><tr><td>中后台 / 低代码 / 组件库，需要和设计体系深度融合、替换局部 UI、多实例隔离</td><td><strong>ew-color-picker</strong></td></tr><tr><td>需要把选色能力嵌进自己的插件体系或运行时</td><td><strong>ew-color-picker</strong>（核心 11 KB，可只保留核心 + 自写插件）</td></tr></tbody></table><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to &quot;相关链接&quot;">​</a></h2><ul><li><a href="./">项目介绍</a> — 设计理念与包结构</li><li><a href="./concepts">核心概念</a> — 挂载点、插件顺序与事件</li><li><a href="./plugin-dev">编写自定义插件</a> — 用自己的 UI 替换内置插件</li></ul>`,29)])])}const u=e(d,[["render",o]]);export{k as __pageData,u as default};
